import numpy as np

def solve_cubic_a1():
    solutions = []
    for b in range(1, 1007):
        # c^3 - 2012*b*c + b^3 - 4024 = 0
        coeffs = [1, 0, -2012*b, b**3 - 4024]
        roots = np.roots(coeffs)
        for r in roots:
            c = r.real
            if c >= b and abs(c - round(c)) < 1e-7:
                c_int = int(round(c))
                if c_int >= b:
                    if 1**3 * (b**3 + c_int**3) == 2012 * (1*b*c_int + 2):
                        solutions.append((1, b, c_int))
    return solutions

